const root = $input.first().json;

function collectNamedArrays(value, found = []) {
  if (!value || typeof value !== "object") return found;
  if (Array.isArray(value.questions)) found.push(value.questions);
  if (Array.isArray(value.urlParameters)) found.push(value.urlParameters);
  if (Array.isArray(value.calculations)) found.push(value.calculations);
  if (Array.isArray(value)) {
    for (const item of value) collectNamedArrays(item, found);
  } else {
    for (const item of Object.values(value)) collectNamedArrays(item, found);
  }
  return found;
}

const fields = {};
for (const list of collectNamedArrays(root)) {
  for (const item of list) {
    if (!item || !item.name) continue;
    fields[String(item.name).trim()] = item.value ?? "";
  }
}

function value(key) {
  const v = fields[key];
  return v === undefined || v === null ? "" : String(v).trim();
}

function pick(...keys) {
  for (const key of keys) {
    const v = value(key);
    if (v) return v;
  }
  return "";
}

function cleanNumber(v) {
  return String(v ?? "").replace(/[₹,%]/g, "").replace(/,/g, "").trim();
}

function rowFor(prefix = "") {
  const keys = (name, label) => prefix
    ? [`${prefix}_${name}`, `${prefix}_${label}`]
    : [name, label];

  return {
    invest_platform: pick(...keys("invest_platform", "Investment Platform"), "invest_platform", "Investment Platform"),
    issuer_type: pick(...keys("issuer_type", "Issuer Type"), "issuer_type", "Issuer Type"),
    sector: pick(...keys("sector", "Sector"), "sector", "Sector"),
    issuer_domain: pick(...keys("issuer_domain", "Issuer Domain"), "issuer_domain", "Issuer Domain"),
    isin: pick(...keys("isin", "ISIN"), "isin", "ISIN"),
    units: cleanNumber(pick(...keys("units", "Units"), "units", "Units")),
    total_investment: cleanNumber(pick(...keys("total_investment", "Total Investment"), `${prefix}_Investment ₹`, "total_investment", "Investment ₹")),
    start_date: pick(...keys("start_date", "Start Date"), "start_date", "Start Date"),
    end_date: pick(...keys("end_date", "End Date"), "end_date", "End Date"),
    coupon_rate_pct: cleanNumber(pick(...keys("coupon_rate_pct", "Coupon Rate"), `${prefix}_Coupon Rate %`, "coupon_rate_pct", "Coupon Rate %")),
    ytm_pct: cleanNumber(pick(...keys("ytm_pct", "YTM"), `${prefix}_YTM %`, "ytm_pct", "YTM %")),
    interest_payout_frequency_in_months: cleanNumber(pick(...keys("interest_payout_frequency_in_months", "Interest Payout Frequency In Months"), "interest_payout_frequency_in_months")),
    maturity_amount: cleanNumber(pick(...keys("maturity_amount", "Maturity Amount"), `${prefix}_Maturity ₹`, "maturity_amount", "Maturity ₹")),
    relationship_manager_name: pick(...keys("relationship_manager_name", "Relationship Manager Name"), "relationship_manager_name"),
    relationship_manager_email: pick(...keys("relationship_manager_email", "Relationship Manager Email"), "relationship_manager_email"),
    relationship_manager_phone: pick(...keys("relationship_manager_phone", "Relationship Manager Phone"), "relationship_manager_phone"),
    notes: pick(...keys("notes", "Notes"), "notes", "Notes")
  };
}

const spreadsheetId = pick("spreadsheet_id", "spreadsheetId", "Spreadsheet ID");
if (!spreadsheetId) {
  throw new Error(`Missing spreadsheet_id. Fields received by n8n: ${Object.keys(fields).join(", ")}`);
}

const prefixes = new Set();
for (const name of Object.keys(fields)) {
  let match = name.match(/^bond_(\d+)_(.+)$/);
  if (match) prefixes.add(`bond_${match[1]}`);
  match = name.match(/^(\d+)_(.+)$/);
  if (match) prefixes.add(match[1]);
}

const rows = prefixes.size
  ? [...prefixes].sort((a, b) => Number(String(a).replace("bond_", "")) - Number(String(b).replace("bond_", ""))).map(prefix => rowFor(prefix)).filter(r => r.isin || r.total_investment)
  : [rowFor("")].filter(r => r.isin || r.total_investment);

return rows.map(row => ({
  json: {
    customer_id: pick("customer_id", "customerId", "Customer ID"),
    spreadsheet_id: spreadsheetId,
    tab_name: pick("tab_name", "tabName") || "Bonds",
    source: pick("source") || "wealthyo_dashboard_bulk_bonds",
    entry_mode: pick("entry_mode") || "bulk",
    ...row
  }
}));
